-- 2.2 跨疾病鉴别诊断横向连线 (分批)
INSERT INTO `medical_relation` (`source_id`, `target_id`, `rel_type`, `rel_desc`) VALUES
('10009', '10940', 'differential', '与惊恐发作鉴别：相比于支气管扩张症，惊恐发作以突发的强烈恐惧感和自主神经症状为主，如心悸、出汗、震颤、呼吸急促及濒死感，而无持续性咳嗽或脓性痰；支气管扩张症常表现为慢性咳嗽伴大量脓性痰、反复肺部感染史，且治疗依赖胸部物理治疗和长期抗生素，而非抗焦虑药物或心理干预。'),
('10018', '10026', 'differential', '与支气管炎鉴别：细支气管炎以喘鸣、呼吸困难及发绀为主要临床表现，且多发生于婴幼儿；而支气管炎以咳嗽、痰多为主，常伴有发热，但喘鸣不显著。细支气管炎多由RSV等病毒引起，常伴随近期病毒性呼吸道感染史，而支气管炎则更常见于成人，与吸烟或空气污染相关。细支气管炎肺部听诊以弥漫性哮鸣音为特征，支气管炎则以痰鸣音和支气管呼吸音为主。'),
('10018', '10432', 'differential', '与肺炎鉴别：细支气管炎主要累及小气道，表现为喘鸣、呼吸困难，肺部体征以哮鸣音为主；而肺炎多累及肺实质，常伴发热、胸痛及肺部湿啰音。细支气管炎多见于婴幼儿且常有RSV感染史，肺炎则多由细菌或病毒引起，且影像学检查可见肺部浸润影。细支气管炎治疗以支持疗法为主，肺炎常需针对病原体的抗生素治疗。'),
('10026', '10432', 'differential', '与肺炎鉴别：支气管炎主要表现为持续性咳嗽、胸闷及黏液分泌，发热多为低至中度且伴随呼吸道症状；而肺炎常伴高热、寒战及肺部实变体征，如叩诊浊音和支气管呼吸音，且需抗生素治疗，而非单纯对症处理。'),
('10026', '10018', 'differential', '与细支气管炎鉴别：支气管炎以胸壁疼痛和局部体征为主，无明显肺泡病变；支气管肺炎则多见于婴幼儿，症状包括喘息、呼吸急促及细湿啰音，且病原体多为病毒，治疗反应与支气管炎差异显著。'),
('10066', '10002', 'differential', '与急性COPD加重感染鉴别：急性哮喘发作期以喘息、呼吸困难和胸闷为主要临床表现，多见于哮喘或过敏体质患者，常由过敏原、冷空气或运动诱发，对吸入型β激动剂治疗反应迅速；而急性COPD加重感染则表现为慢性咳嗽、咳痰加重伴呼吸困难恶化，常有长期吸烟或慢性肺部疾病史，合并感染时可出现发热等全身症状，治疗需联合使用抗生素及支气管扩张剂，且对β激动剂的反应可能不如哮喘显著。'),
('10074', '10940', 'differential', '与惊恐发作鉴别：肺栓塞多表现为胸膜炎性胸痛，吸气时加剧且常位于胸后壁，可能伴发咯血及低氧血症等客观体征；而惊恐发作的胸痛多为非典型性、弥漫性，通常无呼吸困难或咯血，且疼痛不随呼吸变化。肺栓塞患者常具有深静脉血栓形成或近期手术、长期制动等明确病史，而惊恐发作主要与焦虑症相关，无此类血管源性病史。两者治疗反应差异显著，肺栓塞需抗凝治疗，惊恐发作则以镇静、抗焦虑药物为主。'),
('10129', '10940', 'differential', '与惊恐发作鉴别：相比于惊恐发作，肺部肿瘤通常伴有持久的咳嗽、咯血及体重减轻等呼吸系统症状，且存在吸烟或职业暴露史，而惊恐发作表现为突发的胸痛伴濒死感，无持续性症状及客观体征。肺部肿瘤需通过影像学或病理学检查确诊，而惊恐发作主要依据临床症状及排除其他器质性疾病。'),
('10167', '10940', 'differential', '与惊恐发作鉴别：相比于惊恐发作，自发性气胸常表现为单侧突发尖锐胸痛且呼吸困难伴随气胸特有的胸腔叩诊鼓音和听诊呼吸音减低，而惊恐发作多为弥漫性胸痛伴濒死感，无肺部结构异常体征，且疼痛不随呼吸加剧。自发性气胸患者多有慢性肺病史或吸烟史，而惊恐发作无此类病史。治疗上气胸需胸腔减压手术，惊恐发作则以心理干预和药物治疗为主。'),
('10208', '10377', 'differential', '与喉气管炎鉴别：Urti通常以喉咙痛、鼻塞和咳嗽为主，而Croup主要表现为犬吠样咳嗽、声音嘶哑及吸气性喉鸣，且常伴有呼吸困难，尤其是在夜间加重，治疗以支气管扩张剂和类固醇为主，而非单纯对症治疗。'),
('10208', '10392', 'differential', '与会厌炎鉴别：Uurti的疼痛多局限于头部或咽喉，且无明显吞咽困难，而Epiglottitis常伴有严重吞咽痛、呼吸急促及会厌肿胀，需紧急评估气道阻塞风险，治疗以抗生素和气道管理为关键，与Uurti的对症治疗有明显差异。'),
('10251', '10377', 'differential', '与喉气管炎鉴别：病毒性咽炎主要表现为咽部灼痛、吞咽困难及颈部淋巴结肿大，而犬吠样咳嗽、声音嘶哑和吸气性喘鸣是喉气管炎的特征，常伴有发热，但无咽部明显充血或淋巴结肿大；治疗上，病毒性咽炎以支持治疗为主，喉气管炎则可能需要肾上腺素或类固醇雾化治疗。'),
('10251', '10392', 'differential', '与会厌炎鉴别：病毒性咽炎多由近期病毒感染引起，常伴随扁桃体肿大和咽痛，而会厌炎（Epiglottitis）多为细菌感染（如H. influenzae），伴有高热、颈部僵硬及严重呼吸困难，咽部检查可见会厌肿胀，需抗生素治疗且病情进展迅速。'),
('10290', '10940', 'differential', '与百日咳鉴别：惊恐发作主要表现为突发的强烈恐惧感及自主神经症状如心悸、出汗、震颤，而无特征性的咳嗽或吸气相“whoop”声；病程短暂（数分钟至数小时），无传染性，治疗以镇静剂和抗焦虑药物为主，而非抗生素。'),
('10297', '10392', 'differential', '与会厌炎鉴别：相比急性喉炎，会厌炎（Epiglottitis）通常表现为突发高热、咽痛及严重吸气性呼吸困难，伴有颈部僵硬和流涎，疼痛多局限于会厌区域，且需紧急气道管理，治疗以抗生素为主。'),
('10297', '10377', 'differential', '与喉气管炎鉴别：相比急性喉炎，Croup多见于5岁以下儿童，表现为犬吠样咳嗽、喉喘鸣及吸气性呼吸困难，且症状常在夜间加重，治疗需使用糖皮质激素及支气管扩张剂。'),
('10326', '10940', 'differential', '与惊恐发作鉴别：相比于惊恐发作，急性肺水肿通常伴有粉红泡沫样痰及双肺湿啰音等特征性体征，且常有心力衰竭或液体超负荷病史，而惊恐发作多表现为突发濒死感、心悸及无特征性体征的胸痛。'),
('10377', '10392', 'differential', '与会厌炎鉴别：喉气管炎通常表现为犬吠样咳嗽、吸气性喘鸣及声音嘶哑，多伴有发热，且病程呈自限性；而会厌炎以突发严重吸气性呼吸困难为特征，常缺乏典型咳嗽，可能伴有高热，但病史中常有细菌感染（如H. influenzae）接触史，且需紧急气道干预。'),
('10377', '10297', 'differential', '与急性喉炎鉴别：喉气管炎具有特征性犬吠样咳嗽和显著吸气性喘鸣，常伴三凹征及发热；而急性喉炎主要表现为声音嘶哑、咳嗽及发热，通常无喘鸣症状，且多由病毒感染直接引起，治疗以对症支持为主，较少使用糖皮质激素。'),
('10386', '10940', 'differential', '与惊恐发作鉴别：喉痉挛表现为突发性吸气性呼吸困难伴高调喘鸣（stridor），且常有胃食管反流病（GERD）或近期上呼吸道感染病史，治疗需优先处理气道阻塞而非使用镇静药物。'),
('10392', '10377', 'differential', '与喉气管炎鉴别：会厌炎表现为剧烈咽痛、流涎及吞咽困难，疼痛呈刀割样且定位明确，通常伴有高热；而急性喉炎（Croup）主要表现为犬吠样咳嗽、喉鸣和声音嘶哑，疼痛不明显，多见于婴幼儿，病程呈波动性。'),
('10392', '10297', 'differential', '与急性喉炎鉴别：会厌炎的疼痛剧烈且精准定位在咽部及周围区域，常伴随呼吸困难和发热，需要紧急气道管理；而急性喉炎（Acute Laryngitis）以声音嘶哑、咳嗽为主，疼痛多位于声带区域，无吞咽困难及呼吸梗阻表现。'),
('10432', '10026', 'differential', '与支气管炎鉴别：肺炎相较于支气管炎更常表现为胸膜性疼痛（如胸壁锐痛），且肺炎的发热多为持续性，而支气管炎多为胸骨后部不适，常伴喘鸣音，治疗上肺炎需抗生素而支气管炎以止咳化痰为主。'),
('10432', '10018', 'differential', '与细支气管炎鉴别：肺炎与支气管肺泡炎的关键区别在于肺炎多伴发胸膜刺激征及实变体征，而支气管肺泡炎以弥漫性细支气管炎症为主，常表现为呼气性呼吸困难，且肺炎治疗反应与抗生素使用相关，支气管肺泡炎则多依赖抗病毒治疗。'),
('10482', '10567', 'differential', '与阵发性室上性心动过速鉴别：心房颤动表现为绝对不规则的心室反应和脉搏短绌，而阵发性室上性心动过速（Psvt）通常具有规则的心室反应且脉搏强而快；心房颤动常伴有高血压或结构性心脏病病史，Psvt多无明显器质性心脏病史；心房颤动需长期抗凝治疗预防栓塞，Psvt则对腺苷、钙通道阻滞剂等药物治疗反应更显著。'),
('10493', '10526', 'differential', '与心包炎鉴别：心肌炎的胸痛多位于心前区或左胸，呈刺痛或闷痛，且常伴随心力衰竭体征；而心包炎的胸痛多放射至左肩或颈部，呈尖锐刀割样，且常伴有心包摩擦音或心音遥远。心肌炎多有近期病毒感染史，而心包炎可能与心肌梗死后、自身免疫疾病或术后状态相关。心肌炎治疗以支持治疗为主，自身免疫性病例可能使用皮质类固醇，而心包炎常首选非甾体抗炎药或利尿剂。'),
('10526', '10493', 'differential', '与心肌炎鉴别：心包炎的胸痛多为剧烈锐痛，仰卧位时加重而直立位时减轻，常放射至左肩或背部；而心肌炎的胸痛多与活动相关，可能伴随心悸、乏力，且疼痛定位较模糊。心包炎常有近期病毒感染或心肌梗死病史，治疗首选非甾体抗炎药（NSAIDs）或秋水仙碱，心肌炎则可能需抗病毒治疗或免疫抑制剂，且对糖皮质激素的反应不同。'),
('10617', '10678', 'differential', '与不稳定型心绞痛鉴别：目标疾病（Possible NSTEMI/STEMI）通常伴随心肌酶升高及心电图ST段改变或病理性Q波，而不稳定性心绞痛（Unstable Angina）多无心肌酶升高，且心电图可能仅显示暂时性ST段压低或T波倒置。'),
('10617', '10622', 'differential', '与稳定型心绞痛鉴别：目标疾病（可能的非ST段抬高型心肌梗死/ST段抬高型心肌梗死）表现为持续性胸痛超过20分钟且治疗后难以缓解，而稳定型心绞痛发作具有可预测性，通常在体力活动或情绪激动后诱发，休息或含服硝酸甘油数分钟内可缓解。'),
('10622', '10678', 'differential', '与不稳定型心绞痛鉴别：稳定型心绞痛的胸痛通常由运动诱发且休息后可缓解，而不稳定型心绞痛常表现为静息时发作、持续时间延长、疼痛程度更重且休息后不完全缓解；稳定型心绞痛对硝酸酯类药物反应良好，而不稳定型心绞痛可能对常规治疗反应不佳，并伴有心电图ST段压低或T波倒置等动态变化。'),
('10678', '10622', 'differential', '与稳定型心绞痛鉴别：不稳定型心绞痛的胸痛发作频率、持续时间及强度较不稳定，常无明确诱因且可能放射至肩部/下颌，而稳定型心绞痛多由体力活动诱发，休息或含服硝酸甘油后迅速缓解，且疼痛定位更明确。'),
('10735', '10940', 'differential', '与惊恐发作鉴别：相比于惊恐发作，重症肌无力具有特征性的活动后肌无力及疲劳性肌无力，常伴眼睑下垂、复视、咀嚼及吞咽困难，且无自主神经症状如心悸或出汗，治疗反应以胆碱酯酶抑制剂及免疫调节药物为主，而非抗焦虑药物。'),
('10744', '10940', 'differential', '与惊恐发作鉴别：相比于吉兰-巴雷综合征，恐慌发作以突发的强烈恐惧感和自主神经症状为主，如心悸、出汗、震颤，无进行性肌肉无力或反射减弱表现；病史中多与心理压力相关，而非感染或疫苗接种史；治疗反应以抗焦虑药物和心理干预有效，而对免疫治疗无预期效果。'),
('10750', '10940', 'differential', '与惊恐发作鉴别：丛集性头痛表现为单侧剧烈头痛伴典型自主神经症状（如眼痛、结膜充血、鼻塞），而惊恐发作以突发强烈恐惧感和濒死感为特征，常伴有心悸、出汗、震颤等自主神经症状，但无头痛或面部局部体征；丛集性头痛治疗反应以氧疗和曲普坦类药物显著，惊恐发作则对镇静剂及选择性5-羟色胺再摄取抑制剂更敏感；丛集性头痛具有周期性发作模式，惊恐发作多与焦虑障碍相关，且无特定疼痛定位特征。'),
('10787', '10940', 'differential', '与惊恐发作鉴别：相比于恐慌发作，急性肌张力障碍反应以肌肉强直性收缩和异常扭曲运动为特征，常伴随意识清醒；而恐慌发作主要表现为心悸、出汗、颤抖等自主神经症状，无运动障碍。急性肌张力障碍反应多有明确的抗胆碱能药物使用史，而恐慌发作常与焦虑情绪或特定诱因相关。治疗上，急性肌张力障碍反应对抗胆碱能药物（如苯扎托品）反应明显，而恐慌发作则对镇静剂或选择性5-羟色胺再摄取抑制剂（SSRIs）更有效。'),
('10795', '10940', 'differential', '与惊恐发作鉴别：相比于系统性红斑狼疮，惊恐发作以突发强烈恐惧感和植物神经紊乱症状为特征，如心悸、出汗、震颤、呼吸困难等，通常无特征性皮肤表现或器官特异性损害，且不伴有自身免疫病史或对免疫抑制剂的治疗反应。'),
('10833', '10940', 'differential', '与惊恐发作鉴别：结节病以多系统肉芽肿性炎症为特征，常伴有慢性咳嗽、呼吸困难、皮肤红斑或结节、葡萄膜炎及非特异性发热，而惊恐发作主要表现为突发的强烈恐惧感、心悸、出汗、震颤及濒死感等自主神经紊乱症状，无器质性病变证据。结节病常出现肺部影像学特征性病变及HLA-B27等遗传标记，惊恐发作则多伴随焦虑病史且对镇静药物反应显著。结节病治疗依赖免疫抑制剂，惊恐发作则以认知行为治疗及抗焦虑药物为主。'),
('10884', '11465', 'differential', '与局部水肿鉴别：过敏性休克具有全身性反应特征，常伴发皮肤潮红、瘙痒、呼吸困难及血压显著下降，而局部水肿多局限于特定区域，无血流动力学不稳定表现。过敏性休克的体征常包括喉头水肿、支气管痉挛等系统性症状，而局部水肿主要表现为受累部位的非凹陷性肿胀。治疗上过敏性休克需立即使用肾上腺素，而局部水肿通常对肾上腺素无反应。'),
('10928', '10940', 'differential', '与惊恐发作鉴别：相比于变应性鼻窦炎，惊恐发作主要表现为突发性胸闷、心悸、出汗、颤抖、呼吸困难等自主神经症状，伴有濒死感或失控感等强烈精神心理症状，而非鼻部症状；无鼻腔分泌物或鼻黏膜水肿等特征性体征；治疗反应上对鼻用皮质类固醇无效，但可能对镇静剂或抗焦虑药物有反应。'),
('10985', '10940', 'differential', '与恐慌发作鉴别：自发性肋骨骨折以胸椎或肋骨的物理性骨折为基础，常伴随外伤史或骨质疏松症，疼痛具有明确的解剖定位特征并与呼吸运动直接相关；而惊恐发作属于焦虑障碍，表现为突发的强烈恐惧感，疼痛多为非特异性胸闷或窒息感，无明确解剖定位，常伴有心动过速、出汗等自主神经症状，且疼痛持续时间短于20分钟。'),
('11021', '10940', 'differential', '与惊恐发作鉴别：腹股沟疝存在可触及的腹股沟区肿块，疼痛与腹压增加（如咳嗽、提重物）直接相关，且具有明确的解剖学异常；而惊恐发作表现为突发的强烈恐惧感，伴随心悸、出汗、呼吸困难等自主神经症状，无相应解剖结构异常，治疗依赖药物或心理干预而非手术修复。'),
('11065', '10940', 'differential', '与惊恐发作鉴别：相比于贫血，恐慌发作主要表现为突发的强烈恐惧感或濒死感，常伴有胸痛、心悸、呼吸急促及出汗等自主神经症状，而非疲劳、苍白或运动耐力下降。贫血患者通常无明显精神心理症状，而恐慌发作时可出现明显的精神焦虑状态。贫血的体征多与血液学指标异常相关，如心率加快、舌炎等，而恐慌发作的体征多与心血管及呼吸系统过度激活有关。'),
('11116', '11429', 'differential', '与博雷加德综合征鉴别：胃食管反流病主要表现为烧心、反酸及胸骨后烧灼感，常因饮食因素诱发且治疗反应良好；而博雷加德综合征以突发剧烈胸痛伴皮下气肿、纵隔炎征象为特征，通常有剧烈呕吐史，且需紧急手术治疗而非抑酸药物。'),
('11165', '10940', 'differential', '与惊恐发作鉴别：相比于恐慌发作（Panic Attack），胰腺肿瘤常表现为持续性上腹或左上腹疼痛，可能放射至背部，并伴随无痛性黄疸、体重下降及深色尿液等特征性体征；而恐慌发作以突发强烈恐惧感为主，伴有胸闷、心悸等自主神经症状，但无客观体征且疼痛呈短暂性发作。胰腺肿瘤的治疗需手术切除、化疗或姑息治疗，而恐慌发作主要通过心理干预和药物控制症状。'),
('11201', '10940', 'differential', '与惊恐发作鉴别：组胺食物中毒的面部潮红、头痛及速脉等临床表现具有明确的鱼制品摄入史关联，而恐慌发作多表现为突发的胸闷、心悸、濒死感等自主神经症状，常无特定饮食诱因，且治疗反应对β受体阻滞剂或抗焦虑药物更敏感，抗组胺药无效。'),
('11207', '10940', 'differential', '与惊恐发作鉴别：相比于结核病，惊恐发作主要表现为突发性胸痛、窒息感或濒死感，伴有心动过速、出汗等自主神经症状，但无持续性咳嗽、夜间盗汗或体重减轻等特征性表现；体检时无肺部实变体征，而结核病常伴有肺部异常体征；治疗反应上，结核病需长期抗生素治疗，惊恐发作则通过镇静剂或抗焦虑药物缓解。'),
('11232', '10377', 'differential', '与喉气管炎鉴别：相比于流行性感冒，哮吼主要表现为犬吠样咳嗽、声音嘶哑及吸气性喉鸣，常伴有发热但无显著全身症状如肌肉疼痛；而流感则以高热、肌肉酸痛、乏力等全身症状为主，呼吸系统症状以干咳和胸闷为特征。前者多见于儿童，后者更常见于老年人及免疫力低下者。'),
('11232', '10392', 'differential', '与会厌炎鉴别：相比于流行性感冒，会厌炎多表现为突发高热、咽痛、吸气性呼吸困难及声音嘶哑，伴有典型的会厌肿胀体征，且病情进展迅速；而流感则以发热、肌肉疼痛、咽痛及干咳为主要表现，无急进性气道阻塞症状，治疗反应以抗病毒药物为主。'),
('11274', '10940', 'differential', '与惊恐发作鉴别：相比于恐慌发作，克雅氏病具有发热、局部肿胀（chagoma）及淋巴结肿大等特征性感染体征，且病史中常存在拉丁美洲旅行或锥虫暴露史，而恐慌发作主要表现为突发性濒死感、心悸、出汗等自主神经症状，无客观感染证据。克雅氏病的疼痛多为局部性且与感染部位相关，而恐慌发作的胸痛通常由过度通气导致，无明确解剖定位。治疗上克雅氏病需使用抗寄生虫药物，恐慌发作则依赖抗焦虑药物或心理治疗。'),
('11326', '11356', 'differential', '与急性鼻窦炎鉴别：急性中耳炎以耳部锐痛、鼓膜充血或穿孔为特征性体征，且常伴随近期上呼吸道感染史，而急性鼻窦炎主要表现为面部胀痛、脓性鼻涕及鼻腔黏膜充血，多与鼻病毒感染或过敏性鼻炎相关。'),
('11326', '11401', 'differential', '与慢性鼻窦炎鉴别：急性中耳炎具有突发性剧烈耳痛及发热，治疗反应以抗生素和止痛药为主；慢性鼻窦炎则表现为持续性鼻塞、嗅觉减退及黏膜慢性炎症，缺乏急性发作时的剧烈疼痛和鼓膜异常体征。'),
('11356', '11326', 'differential', '与急性中耳炎鉴别：急性鼻窦炎主要表现为面部疼痛（如前额、脸颊、眼睛等鼻窦区域），伴有脓性鼻分泌物及鼻塞，常有发热；而急性中耳炎以耳部疼痛、听力下降及鼓膜充血/膨出为特征性体征，疼痛多放射至头部而非面部，且通常无脓性鼻分泌物。治疗上，急性鼻窦炎以鼻用减充血剂和抗生素为主，而急性中耳炎更依赖抗生素及耳部局部治疗。'),
('11356', '11401', 'differential', '与慢性鼻窦炎鉴别：急性鼻窦炎症状持续时间短（<4周），常伴发热及明显的面部压痛，而慢性鼻窦炎病程超过12周，症状以持续性鼻塞、嗅觉减退为主，无发热，且可能伴有鼻腔黏膜苍白水肿或息肉样变。治疗反应方面，急性鼻窦炎对鼻用减充血剂和抗生素反应较好，慢性鼻窦炎则需长期使用鼻用类固醇或抗过敏药物。'),
('11401', '11326', 'differential', '与急性中耳炎鉴别：慢性鼻窦炎与急性中耳炎的关键区别在于疼痛部位及伴随症状：前者以鼻腔及面部持续性疼痛（如鼻窦区、额头、面颊）为主，常伴嗅觉减退和脓性鼻分泌物，而后者主要表现为耳部疼痛，常伴有发热、听力下降及鼓膜充血等中耳特征性体征。'),
('11401', '11356', 'differential', '与急性鼻窦炎鉴别：慢性鼻窦炎病程超过10天且持续3个月以上，治疗反应对短期抗生素效果差，而急性鼻窦炎多突发于感冒后，症状持续≤4周，常伴发热与脓性鼻涕，抗生素治疗通常有效。'),
('11465', '10884', 'differential', '与过敏性休克鉴别：局部水肿通常表现为局限性、压凹性肿胀，常伴有疼痛或压痛，且无全身过敏反应症状；而过敏性休克（anaphylaxis）为急性全身性过敏反应，主要特征为皮肤红斑、瘙痒、呼吸困难、低血压及意识障碍，不以局部肿胀为突出表现。局部水肿可能与非甾体抗炎药（NSAIDs）使用相关，而过敏性休克需紧急肾上腺素治疗，不依赖抗炎药物。两者病程发展速度差异显著，局部水肿多为缓发，过敏性休克则呈突发性进展。');